def linear_search(items, target):   # best O(1), worst O(n)
    for i, item in enumerate(items):
        if item == target:
            return i
    return -1

def reversed_copy(items):           # O(n) extra space: a new list
    return items[::-1]

def reverse_in_place(items):        # O(1) extra space: two indexes
    left, right = 0, len(items) - 1
    while left < right:
        items[left], items[right] = items[right], items[left]
        left += 1
        right -= 1

